"use client";
import { Button as AriaButton, type ButtonProps } from "react-aria-components";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/folio-utils";
import { spring } from "@/lib/folio-motion";

export function Button({
  className,
  variant = "secondary",
  children,
  ...props
}: ButtonProps & { variant?: "primary" | "secondary" | "ghost" }) {
  const reduced = useReducedMotion();
  return (
    <AriaButton
      {...props}
      className={(state) =>
        cn(
          "inline-flex min-h-9 items-center justify-center gap-2 rounded-md px-3 py-2 text-[14px] leading-[20px] font-medium cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-kumo-focus disabled:opacity-40 disabled:cursor-not-allowed disabled:shadow-none disabled:bg-none",
          variant === "primary"
            ? "bg-kumo-brand bg-[image:var(--background-image-folio-brand)] text-folio-on-brand shadow-folio-brand ring-1 ring-kumo-brand-hover data-[hovered]:brightness-105 data-[pressed]:bg-none data-[pressed]:shadow-folio-pressed data-[pressed]:translate-y-px motion-reduce:data-[pressed]:translate-y-0"
            : variant === "ghost"
              ? "hover:bg-kumo-tint"
              : "bg-kumo-control bg-[image:var(--background-image-folio-control)] text-kumo-default shadow-folio-raised ring-1 ring-kumo-line data-[hovered]:bg-kumo-fill-hover data-[pressed]:bg-none data-[pressed]:shadow-folio-pressed data-[pressed]:translate-y-px motion-reduce:data-[pressed]:translate-y-0",
          typeof className === "function" ? className(state) : className,
        )
      }
    >
      {(state) => (
        <motion.span
          className="inline-flex items-center justify-center gap-2 leading-[20px] [&>svg]:block [&>svg]:size-4 [&>svg]:shrink-0"
          initial={false}
          animate={{
            scale: state.isPressed && !state.isDisabled && !reduced ? 0.96 : 1,
          }}
          transition={reduced ? { duration: 0 } : spring}
        >
          {typeof children === "function" ? children(state) : children}
        </motion.span>
      )}
    </AriaButton>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import {
  TextField as AriaTextField,
  Label,
  Input,
  Text,
  FieldError,
  type TextFieldProps as AriaTextFieldProps,
} from "react-aria-components";

export function TextField({
  label,
  placeholder,
  description,
  errorMessage,
  onFocusChange,
  ...props
}: AriaTextFieldProps & {
  label: string;
  placeholder?: string;
  description?: string;
  errorMessage?: string;
}) {
  const [focused, setFocused] = useState(false);
  const reduced = useReducedMotion();
  return (
    <AriaTextField
      {...props}
      className="flex flex-col gap-1.5 text-[14px] leading-[20px]"
      onFocusChange={(value) => {
        setFocused(value);
        onFocusChange?.(value);
      }}
    >
      <Label className="font-medium">{label}</Label>
      <div className="relative">
        <Input
          placeholder={placeholder}
          className="w-full rounded-md bg-kumo-control bg-[image:var(--background-image-folio-inset)] shadow-folio-inset px-3 py-2 text-[14px] leading-[20px] text-kumo-default placeholder:text-kumo-placeholder ring-1 ring-kumo-line outline-none focus:ring-2 focus:ring-kumo-focus"
        />
        <motion.span
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-2 bottom-0 h-0.5 origin-left rounded bg-kumo-brand"
          initial={false}
          animate={{ scaleX: focused ? 1 : 0, opacity: focused ? 1 : 0 }}
          transition={{ duration: reduced ? 0 : 0.18 }}
        />
      </div>
      {description && (
        <Text slot="description" className="text-xs text-kumo-subtle">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-kumo-danger">
        {errorMessage}
      </FieldError>
    </AriaTextField>
  );
}

"use client";
import {
  Checkbox as AriaCheckbox,
  type CheckboxProps,
} from "react-aria-components";
import { motion, useReducedMotion } from "motion/react";

export function Checkbox({ children, ...props }: CheckboxProps) {
  const reduced = useReducedMotion();
  return (
    <AriaCheckbox
      {...props}
      className="group flex items-center gap-2.5 text-[14px] leading-[20px] cursor-pointer data-[disabled]:cursor-not-allowed data-[disabled]:opacity-40"
    >
      {(state) => (
        <>
          <span className="flex size-4 shrink-0 items-center justify-center rounded bg-kumo-control bg-[image:var(--background-image-folio-inset)] shadow-folio-inset group-data-[selected]:bg-none group-data-[selected]:shadow-folio-brand group-data-[indeterminate]:bg-none ring-1 ring-kumo-line group-data-[selected]:bg-kumo-brand group-data-[selected]:ring-kumo-brand group-data-[indeterminate]:bg-kumo-brand group-data-[focus-visible]:ring-2 group-data-[focus-visible]:ring-kumo-focus">
            <motion.svg
              aria-hidden="true"
              viewBox="0 0 16 16"
              className="size-3 text-folio-on-brand"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <motion.path
                d={state.isIndeterminate ? "M3 8h10" : "M3 8l3 3 7-7"}
                initial={false}
                animate={{
                  pathLength: state.isSelected || state.isIndeterminate ? 1 : 0,
                  opacity: state.isSelected || state.isIndeterminate ? 1 : 0,
                }}
                transition={{ duration: reduced ? 0 : 0.16, ease: "easeOut" }}
              />
            </motion.svg>
          </span>
          <span className="min-w-0 leading-[20px]">
            {typeof children === "function" ? children(state) : children}
          </span>
        </>
      )}
    </AriaCheckbox>
  );
}

"use client";
import { Switch as AriaSwitch, type SwitchProps } from "react-aria-components";
import { motion, useReducedMotion } from "motion/react";
import { spring } from "@/lib/folio-motion";

export function Switch({ children, ...props }: SwitchProps) {
  const reduced = useReducedMotion();
  return (
    <AriaSwitch
      {...props}
      className="group flex items-center gap-3 text-[14px] leading-[20px] cursor-pointer data-[disabled]:cursor-not-allowed data-[disabled]:opacity-40"
    >
      {(state) => (
        <>
          <span className="flex h-5 w-9 shrink-0 items-center rounded-full bg-kumo-interact shadow-folio-inset ring-1 ring-kumo-line px-0.5 group-data-[selected]:bg-kumo-brand group-data-[focus-visible]:ring-2 ring-kumo-focus">
            <motion.span
              aria-hidden="true"
              className="h-4 w-4 rounded-full bg-folio-on-brand bg-[image:var(--background-image-folio-knob)] shadow-folio-knob"
              initial={false}
              animate={{ x: state.isSelected ? 16 : 0 }}
              transition={reduced ? { duration: 0 } : spring}
            />
          </span>
          <span className="min-w-0 leading-[20px]">
            {typeof children === "function" ? children(state) : children}
          </span>
        </>
      )}
    </AriaSwitch>
  );
}

import { type ComponentProps } from "react";
import { cn } from "@/lib/folio-utils";
const variants = {
  neutral: "bg-kumo-tint text-kumo-subtle",
  success: "bg-kumo-success-tint text-kumo-success",
  warning: "bg-kumo-warning-tint text-kumo-warning",
  danger: "bg-kumo-danger-tint text-kumo-danger",
  info: "bg-kumo-info-tint text-kumo-info",
};
export function Badge({
  variant = "neutral",
  className,
  ...props
}: ComponentProps<"span"> & { variant?: keyof typeof variants }) {
  return (
    <span
      {...props}
      className={cn(
        "inline-flex items-center justify-center gap-1 rounded-md px-2 py-1 text-xs leading-4",
        variants[variant],
        className,
      )}
    />
  );
}

import { type ComponentProps } from "react";
import { cn } from "@/lib/folio-utils";
export function Card({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      {...props}
      className={cn(
        "rounded-xl bg-kumo-base bg-[image:var(--background-image-folio-card)] p-5 text-kumo-default shadow-folio-card",
        className,
      )}
    />
  );
}

"use client";
import { useId } from "react";
import {
  Tabs as AriaTabs,
  TabList as AriaTabList,
  Tab as AriaTab,
  TabPanel as AriaTabPanel,
  type TabsProps,
  type TabListProps,
  type TabProps,
  type TabPanelProps,
} from "react-aria-components";
import { LayoutGroup, motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/folio-utils";
export function Tabs(props: TabsProps) {
  const id = useId();
  return (
    <LayoutGroup id={id}>
      <AriaTabs {...props} />
    </LayoutGroup>
  );
}
export function TabList<T extends object>({
  className,
  ...props
}: TabListProps<T>) {
  return (
    <AriaTabList
      {...props}
      className={cn(
        "flex border-b border-kumo-hairline",
        typeof className === "string" ? className : undefined,
      )}
    />
  );
}
export function Tab({ children, className, ...props }: TabProps) {
  const reduced = useReducedMotion();
  return (
    <AriaTab
      {...props}
      className={(state) =>
        cn(
          "relative cursor-pointer px-3 py-2 text-sm text-kumo-subtle outline-none data-[selected]:text-kumo-link data-[focus-visible]:ring-2 ring-kumo-focus data-[disabled]:opacity-40",
          typeof className === "function" ? className(state) : className,
        )
      }
    >
      {(state) => (
        <>
          {typeof children === "function" ? children(state) : children}
          {state.isSelected && (
            <motion.span
              className="tab-indicator absolute inset-x-0 -bottom-px h-0.5 bg-kumo-brand"
              layoutId="tab-underline"
              transition={{ duration: reduced ? 0 : 0.2 }}
            />
          )}
        </>
      )}
    </AriaTab>
  );
}
export function TabPanel({ children, className, ...props }: TabPanelProps) {
  const reduced = useReducedMotion();
  return (
    <AriaTabPanel
      {...props}
      className={(state) =>
        cn(
          "py-4 text-sm text-kumo-default outline-none focus-visible:ring-2 ring-kumo-focus",
          typeof className === "function" ? className(state) : className,
        )
      }
    >
      {(state) => (
        <motion.div
          initial={{ opacity: 0, y: reduced ? 0 : 3 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: reduced ? 0 : 0.15 }}
        >
          {typeof children === "function" ? children(state) : children}
        </motion.div>
      )}
    </AriaTabPanel>
  );
}

"use client";
import { type ReactNode } from "react";
import {
  AnimatePresence,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import { Modal, ModalOverlay } from "react-aria-components";

const MotionOverlay = motion.create(ModalOverlay);
const MotionModal = motion.create(Modal);

// Keep React Aria's portal, focus trap, scroll lock and restore-focus lifecycle.
function OverlayPresence({
  children,
  onOpenChange,
}: {
  children: ReactNode;
  onOpenChange?: (open: boolean) => void;
}) {
  const present = useIsPresent();
  const reduced = useReducedMotion();
  return (
    <MotionOverlay
      isOpen={present}
      isExiting={!present}
      onOpenChange={onOpenChange}
      isDismissable
      className="fixed inset-0 z-50 flex items-center justify-center bg-folio-backdrop p-5 backdrop-blur-sm"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: reduced ? 0 : 0.16 }}
    >
      {children}
    </MotionOverlay>
  );
}

export function AnimatedOverlay({
  isOpen,
  onOpenChange,
  children,
}: {
  isOpen: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
}) {
  return (
    <AnimatePresence>
      {isOpen && (
        <OverlayPresence key="overlay" onOpenChange={onOpenChange}>
          {children}
        </OverlayPresence>
      )}
    </AnimatePresence>
  );
}

export function AnimatedModal({
  children,
  className = "w-full max-w-lg max-h-[90vh] overflow-auto rounded-xl bg-kumo-base bg-[image:var(--background-image-folio-card)] p-6 text-kumo-default shadow-folio-card",
}: {
  children: ReactNode;
  className?: string;
}) {
  const reduced = useReducedMotion();
  return (
    <MotionModal
      className={className}
      initial={{ opacity: 0, y: reduced ? 0 : 12, scale: reduced ? 1 : 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: reduced ? 0 : 6, scale: reduced ? 1 : 0.99 }}
      transition={{ duration: reduced ? 0 : 0.18, ease: [0.22, 1, 0.36, 1] }}
    >
      {children}
    </MotionModal>
  );
}

"use client";
import {
  Select as AriaSelect,
  Label,
  Button,
  SelectValue,
  Popover,
  ListBox,
  ListBoxItem,
  Text,
  FieldError,
  type SelectProps as AriaSelectProps,
} from "react-aria-components";
import { ChevronDown, Check } from "lucide-react";
export interface SelectOption {
  id: string;
  label: string;
  isDisabled?: boolean;
}
export function Select({
  label,
  options,
  description,
  errorMessage,
  ...props
}: Omit<AriaSelectProps<SelectOption>, "children"> & {
  label: string;
  options: SelectOption[];
  description?: string;
  errorMessage?: string;
}) {
  return (
    <AriaSelect
      {...props}
      disabledKeys={
        props.disabledKeys ??
        options.filter((x) => x.isDisabled).map((x) => x.id)
      }
      className="flex w-full flex-col gap-1.5 text-sm text-kumo-default"
    >
      <Label className="font-medium">{label}</Label>
      <Button className="flex min-h-9 items-center justify-between gap-3 rounded-md bg-kumo-control bg-[image:var(--background-image-folio-inset)] px-3 py-2 text-left shadow-folio-inset ring-1 ring-kumo-line outline-none data-[focus-visible]:ring-2 ring-kumo-focus data-[disabled]:opacity-40">
        <SelectValue />
        <ChevronDown size={16} aria-hidden="true" />
      </Button>
      {description && (
        <Text slot="description" className="text-xs text-kumo-subtle">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-kumo-danger">
        {errorMessage}
      </FieldError>
      <Popover className="z-50 w-[var(--trigger-width)] min-w-44 rounded-lg bg-kumo-base p-1 text-kumo-default shadow-folio-card">
        <ListBox items={options} className="outline-none">
          {(option) => (
            <ListBoxItem
              id={option.id}
              textValue={option.label}
              className="flex cursor-pointer items-center justify-between gap-4 rounded px-3 py-2 text-sm outline-none data-[focused]:bg-kumo-tint data-[disabled]:opacity-40"
            >
              {({ isSelected }) => (
                <>
                  {option.label}
                  {isSelected && <Check size={14} />}
                </>
              )}
            </ListBoxItem>
          )}
        </ListBox>
      </Popover>
    </AriaSelect>
  );
}

"use client";
import { useState, type ComponentProps } from "react";
import { cn } from "@/lib/folio-utils";
export function Avatar({
  src,
  name,
  className,
  ...props
}: Omit<ComponentProps<"span">, "children"> & { name: string; src?: string }) {
  const [failedSource, setFailedSource] = useState<string>();
  const initials = name
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
  return (
    <span
      {...props}
      role="img"
      aria-label={name}
      className={cn(
        "inline-flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-kumo-tint text-xs text-kumo-default",
        className,
      )}
    >
      {src && failedSource !== src ? (
        <img
          src={src}
          alt=""
          className="size-full object-cover"
          onError={() => setFailedSource(src)}
        />
      ) : (
        initials
      )}
    </span>
  );
}

import { type ReactNode, type ComponentProps } from "react";
import { cn } from "@/lib/folio-utils";
const variants = {
  info: "bg-kumo-info-tint text-kumo-info",
  success: "bg-kumo-success-tint text-kumo-success",
  warning: "bg-kumo-warning-tint text-kumo-warning",
  danger: "bg-kumo-danger-tint text-kumo-danger",
};
export function Alert({
  title,
  children,
  icon,
  variant = "info",
  className,
  ...props
}: Omit<ComponentProps<"div">, "title"> & {
  title: ReactNode;
  icon?: ReactNode;
  variant?: keyof typeof variants;
}) {
  return (
    <div
      role={variant === "danger" ? "alert" : "status"}
      {...props}
      className={cn(
        "flex items-start gap-3 rounded-lg p-3 text-sm",
        variants[variant],
        className,
      )}
    >
      {icon && (
        <span className="mt-0.5 shrink-0" aria-hidden="true">
          {icon}
        </span>
      )}
      <div>
        <div className="font-medium">{title}</div>
        {children && <div className="mt-1 text-xs">{children}</div>}
      </div>
    </div>
  );
}

"use client";
import { type ReactNode } from "react";
import {
  TooltipTrigger,
  Tooltip as AriaTooltip,
  type TooltipProps,
} from "react-aria-components";
import { motion, useReducedMotion } from "motion/react";
export function Tooltip({
  children,
  content,
  delay = 400,
  ...props
}: Omit<TooltipProps, "children"> & {
  children: ReactNode;
  content: ReactNode;
  delay?: number;
}) {
  const reduced = useReducedMotion();
  return (
    <TooltipTrigger delay={delay}>
      {children}
      <AriaTooltip
        {...props}
        className="z-50 rounded-md bg-kumo-contrast px-3 py-2 text-xs text-kumo-inverse shadow-folio-raised"
      >
        <motion.div
          initial={{ opacity: 0, y: reduced ? 0 : 3 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: reduced ? 0 : 0.12 }}
        >
          {content}
        </motion.div>
      </AriaTooltip>
    </TooltipTrigger>
  );
}
